import{_ as o,C as t,o as r,c as s,E as a,a2 as c}from"./chunks/framework.Cm6XCzck.js";const l="/joinwell52/assets/execution-artifacts-20260906/01-cancellation-inline-en-v1.png",m=JSON.parse('{"title":"You Clicked Cancel. Which Step Did It Actually Cancel? An Agent Execution-Boundary Experiment","description":"","frontmatter":{"schema":"publication-candidate-article/v2","title":"You Clicked Cancel. Which Step Did It Actually Cancel? An Agent Execution-Boundary Experiment","date":"2026-09-06","published_date":"2026-09-07","column":"open-source-engineering","category":"daily","article_type":"engineering-case-study","edition":"research-center","summary":"Requesting cancellation, accepting it, and preventing an action are different facts. Controlled tests of a real approval service and session adapter separate existing protections from an untested host-queue window.","cover":"/assets/execution-artifacts-20260906/01-cancellation-cover-v2.png","language":"en","lifecycle":"Published","publication_authorized":true,"evidence_status":"Controlled study complete; no new product defect or development authorization","pageClass":"execution-artifacts-article"},"headers":[],"relativePath":"en/engineering/2026-09-06-cancellation-execution-boundary.md","filePath":"en/engineering/2026-09-06-cancellation-execution-boundary.md","lastUpdated":1788751356000}'),d={name:"en/engineering/2026-09-06-cancellation-execution-boundary.md"};function p(h,e,u,f,g,w){const n=t("ArticleCover"),i=t("ArticleTableScroll");return r(),s("div",null,[a(n,{image:"/assets/execution-artifacts-20260906/01-cancellation-cover-v2.png",kicker:"Open-source Engineering · Controlled Study",title:"You Clicked Cancel. Which Step Did It Actually Cancel? An Agent Execution-Boundary Experiment",summary:"Requesting cancellation, accepting it, and preventing an action are different facts. Controlled tests of a real approval service and session adapter separate existing protections from an untested host-queue window.",version:"2026-09-06",languageHref:"/zh/engineering/2026-09-06-cancellation-execution-boundary",languageLabel:"中文"}),a(i,{language:"en"}),e[0]||(e[0]=c('<p><a href="https://joinwell52-ai.github.io/joinwell52/assets/execution-artifacts-20260906/01-cancellation-cover-v2.png" target="_blank" rel="noreferrer">View full-resolution cover</a></p><h1 id="you-clicked-cancel-which-step-did-it-actually-cancel-an-agent-execution-boundary-experiment" tabindex="-1">You Clicked Cancel. Which Step Did It Actually Cancel? An Agent Execution-Boundary Experiment <a class="header-anchor" href="#you-clicked-cancel-which-step-did-it-actually-cancel-an-agent-execution-boundary-experiment" aria-label="Permalink to &quot;You Clicked Cancel. Which Step Did It Actually Cancel? An Agent Execution-Boundary Experiment&quot;">​</a></h1><p>One unsettling moment with an AI assistant editing your files is changing your mind while it still says it is working.</p><p>You click Cancel. Should it stop starting new actions, immediately terminate the running command, or restore a partially written file? If the write has already begun, should it stop halfway or finish and then stop?</p><p>These are different promises. A cancellation button can express a clear user intention, but clicking it alone does not prove the executor accepted the request—or that an external action has not happened.</p><p>Our recent experiment produced a sequence that was easy to misread: the executor waited, we requested cancellation, and the file was subsequently written. From that sequence alone, “it executed after cancellation” sounds plausible. Reading the receipt changed the conclusion: <strong>the cancellation request had never been accepted.</strong></p><p>This is not a report of a cancellation vulnerability we have fixed. It is an investigation into tracing “I asked it to stop” to “this particular step actually stopped.”</p><p>We examine three distinct boundaries: <strong>cancelling a pending approval, ending a session, and aborting before an action</strong>. They are not one interface with one promise. We first test the approval service, then the session adapter; the additional pre-action abort check is a research control, not an end-to-end test of a UI button.</p><h2 id="_1-a-window-worth-investigating-how-much-waiting-follows-the-check" tabindex="-1">1. A window worth investigating: how much waiting follows the check? <a class="header-anchor" href="#_1-a-window-worth-investigating-how-much-waiting-follows-the-check" aria-label="Permalink to &quot;1. A window worth investigating: how much waiting follows the check?&quot;">​</a></h2><p>OpenHands is an open-source project for software-development agents. Its SDK supplies capabilities such as tool execution. An agent here is an AI assistant that can act through tools, rather than merely produce conversational answers.</p><p>OpenHands SDK <a href="https://github.com/OpenHands/software-agent-sdk/pull/4866" target="_blank" rel="noreferrer">proposal #4866</a> examined a concrete sequence: check cancellation before executing a tool, then wait for a resource lock. If cancellation occurs during that wait, will the tool still be invoked after the lock becomes available? The proposal added another check after acquisition. As checked on September 6, 2026, it was closed without merging; the author said it would be refiled with corrected evidence. It is a research lead, not an upstream incident independently reproduced here or a delivered fix.</p><p>The valuable question is: <strong>if a check and an action are separated by waiting, does the earlier decision still hold?</strong></p><p>A tool might need an environment occupied by another task. Being allowed when it enters a queue does not establish that it should still run when its turn arrives. But before diagnosing a defect, we need to know what the cancellation endpoint promises to revoke, whether the request succeeded, and which layer owns the wait.</p><p>We therefore tested the existing boundaries before adding another check to our system.</p><h2 id="_2-first-counterexample-execution-after-a-deadline-is-not-necessarily-expired-authorization" tabindex="-1">2. First counterexample: execution after a deadline is not necessarily expired authorization <a class="header-anchor" href="#_2-first-counterexample-execution-after-a-deadline-is-not-necessarily-expired-authorization" aria-label="Permalink to &quot;2. First counterexample: execution after a deadline is not necessarily expired authorization&quot;">​</a></h2><p>CodeFlowMu is the local multi-agent collaboration system we are developing. It organizes work around task files, execution sessions, and evidence. This study used source baseline <code>c008d9db91a21136fc61a4f60314e22db395d5d2</code>, invoking the real approval service in isolated synthetic directories. We did not cancel users&#39; live tasks or change product code.</p><p>We began with the ordinary path: approve an exact file operation, execute once, and try to replay it. In both rounds, the first execution succeeded and produced one file effect. Replay returned <code>APPROVAL_ALREADY_CONSUMED</code>: the approval had already been consumed.</p><p>Next came time. We used the service&#39;s injectable clock to set a 30-second pending-review deadline, rather than relying on random delays to produce a race.</p><table tabindex="0"><thead><tr><th>Scenario</th><th>Observed result, matching in both rounds</th><th>Supported conclusion</th></tr></thead><tbody><tr><td>Cancel before approval, then try execution</td><td>Request enters cancelled state; execution with an unissued credential is rejected; 0 file effects</td><td>Verifies the cancellation state and rejection of unapproved execution, not revocation of an approved token</td></tr><tr><td>Leave the request unapproved beyond 30 seconds</td><td>Expired; approval rejected; 0 file effects</td><td>The pending-review deadline works</td></tr><tr><td>Approve before the deadline, execute at second 31</td><td>Succeeded; 1 file effect</td><td>Identify what the deadline governs before reporting a defect</td></tr></tbody></table><p>The third row looks suspicious: <code>expires_at</code> says second 30, so why is execution allowed at second 31?</p><p>The first row also needs its premise preserved: the request had not been approved, so the execution attempt did not use an issued token. It checks pending cancellation and rejection of unapproved execution, not revocation of an already approved token.</p><p>The source provides a clear answer to the timing question: this deadline governs <strong>waiting for approval</strong>. An existing test explicitly requires an approved token to remain usable beyond the pending-review deadline. A token is the approval credential presented at execution; its expiration rules must be read from its actual contract.</p><p>The observation is therefore not an authorization-expiry bypass. A pending-review deadline is not a universal execution deadline after approval.</p><p>If a product later needs “even an approved action must not run after ten minutes,” that is another rule to define and verify. We cannot assign an unpromised meaning to a field and then label its implementation a vulnerability.</p><h2 id="_3-second-counterexample-why-was-cancellation-rejected-while-the-executor-waited" tabindex="-1">3. Second counterexample: why was cancellation rejected while the executor waited? <a class="header-anchor" href="#_3-second-counterexample-why-was-cancellation-rejected-while-the-executor-waited" aria-label="Permalink to &quot;3. Second counterexample: why was cancellation rejected while the executor waited?&quot;">​</a></h2><p>The more revealing experiment inserted a script-controlled waiting point after the approval service entered its executor callback—the point where the service hands control to concrete execution code. We paused the callback, requested cancellation, and then released it.</p><p>The condition matters: the research script injected the wait. The local file executor under test uses synchronous file operations. This did not reproduce an OpenHands-style resource-lock queue in the product.</p><table tabindex="0"><thead><tr><th>Scenario</th><th>Cancellation receipt</th><th>Final file effects</th><th>Interpretation</th></tr></thead><tbody><tr><td>Enter callback, wait, request cancellation, release</td><td><code>APPROVAL_NOT_PENDING</code>; rejected</td><td>1</td><td>Not successful cancellation followed by execution</td></tr><tr><td>Same wait; research callback checks its own abort flag after release</td><td>Cancellation still rejected</td><td>0; callback throws</td><td>Demonstrates the timing of a check, not a new product capability</td></tr><tr><td>Write effect first; request cancellation while waiting to finish</td><td>Rejected</td><td>The existing 1 effect remains</td><td>A later request is not automatic rollback</td></tr></tbody></table><p>Each scenario used a new isolated experiment directory in each of two rounds; results matched.</p><p><img src="'+l+'" alt="Cancellation receipts versus file effects in three controlled scenarios"></p><p><em>Figure 1. A1, A4, and A5. The extra abort check in the third row belongs only to the research callback. Waiting is not a real product resource queue; the pending-approval scenario has no issued token. Source: this study&#39;s controlled observations; AI-generated explanatory illustration.</em></p><p><a href="https://joinwell52-ai.github.io/joinwell52/assets/execution-artifacts-20260906/01-cancellation-inline-en-v1.png" target="_blank" rel="noreferrer">View full-resolution figure</a></p><p>Why did cancellation fail in the first scenario? After validating approval state, token, and request digest, the service records <code>executing</code> and invokes the callback. Its cancellation endpoint accepts only approvals that are still pending.</p><p>Thus <code>executing</code> during the wait does not prove the file was already written. But <code>APPROVAL_NOT_PENDING</code> does establish that this approval-cancellation request failed. Both facts must survive the analysis.</p><p>The second scenario is a deliberate mechanism control: after waiting, the research callback observes its abort flag and skips the real file executor. Moving the check can change the outcome. The operative signal here is the research script&#39;s abort flag, not the rejected approval-cancellation request.</p><p>That is the dividing line in this study: <strong>a cancellation request is not evidence of cancellation acceptance; entering an executor is not evidence that its effect has happened.</strong></p><h2 id="_4-a-new-topic-should-not-erase-existing-protections" tabindex="-1">4. A new topic should not erase existing protections <a class="header-anchor" href="#_4-a-new-topic-should-not-erase-existing-protections" aria-label="Permalink to &quot;4. A new topic should not erase existing protections&quot;">​</a></h2><p>The approval service is not the entire chain. CodeFlowMu also has session adapters that connect to coding agents, receive requests, handle approval replies, and end sessions.</p><p>We tested our Codex session adapter using the real <code>CodexAppServerRunHandle</code> class attached to an in-memory fake process transport. We did not start actual Codex or execute terminal tools.</p><p>There was one observation point: whether a final approval reply was sent.</p><table tabindex="0"><thead><tr><th>Scenario</th><th>Approval replies actually sent per round</th></tr></thead><tbody><tr><td>Normal request, not cancelled before replying</td><td>1</td></tr><tr><td>Request received; session cancelled before asynchronous resolution returns</td><td>0</td></tr><tr><td>Late request arrives after session cancellation</td><td>0</td></tr></tbody></table><p>All three scenarios ran twice. They demonstrate protection against late replies after session termination at the tested adapter boundary. It would be wrong to say the system has no final check at all.</p><p>But not sending a reply is different from preventing tool execution inside a real host—the program actually running the agent and its tools. If a reply has already been delivered and the tool then waits for a resource, the rules for that window still need testing in the particular host.</p><p>A correct local adapter cannot guarantee another process&#39;s behavior. Equally, an upstream concern cannot erase the protections already verified locally.</p><h2 id="_5-what-evidence-should-cancellation-leave" tabindex="-1">5. What evidence should cancellation leave? <a class="header-anchor" href="#_5-what-evidence-should-cancellation-leave" aria-label="Permalink to &quot;5. What evidence should cancellation leave?&quot;">​</a></h2><p>For a follow-up study of a real tool queue, the most discriminating record is not a final <code>cancelled</code> label. It is an aligned timeline:</p><blockquote><p>Cancellation request arrives → accepted or rejected receipt → waiting ends → final validity check → real action begins → effect and completion.</p></blockquote><p>This is a proposed experiment, not a unified interface implemented in this study.</p><p>Each point answers a different question. Acceptance specifies the promise. The actual start point shows whether that promise could take effect in time. Effect evidence identifies anything still requiring reconciliation or remediation. An external action that already occurred needs separately defined compensation; stopping later computation cannot make it never have happened.</p><p>An engineering team should first check three things:</p><ul><li>Does the interface turn “requesting cancellation” into “stopped” prematurely?</li><li>Does each cancellation endpoint address pending approval, an entire session, or an active operation?</li><li>For resource waiting, can we show that the check runs after the wait and before the action, not merely at function entry?</li></ul><p>The study separates existing protection from the next window to test: approval cancellation addresses pending requests, the session adapter blocks late replies in the tested scenarios, and real tool queues after reply delivery still require separate testing. Further development should follow evidence at that boundary.</p><p><strong>Reliable cancellation is not about making every component display “cancelled.” It is about explaining where the request was accepted, which step it prevented, and which facts it did not change.</strong></p><h2 id="evidence-and-scope" tabindex="-1">Evidence and scope <a class="header-anchor" href="#evidence-and-scope" aria-label="Permalink to &quot;Evidence and scope&quot;">​</a></h2><p>This article uses seven approval scenarios and three adapter scenarios, each run twice. These are not production-incident statistics or a security accuracy benchmark. The baseline test set, comprising two existing test files, also ran twice, with 39 passing tests in total, 0 failures, and 0 skips per round. Adding those counts does not create an end-to-end guarantee.</p><p>The <a href="/joinwell52/en/research/evidence/2026-09-06-execution-artifact-continuity">bilingual evidence companion</a> provides all exported observations, provenance, two baseline logs, adapted research probes, and an integrity checker. Local paths and process IDs are removed; outcomes and ordering are retained. The adapter&#39;s normal scenario ends in cancellation only because of test cleanup, not because normal execution failed. Checking the published records does not rerun the product; running the probes additionally requires authorized access to the fixed CodeFlowMu source and its dependencies.</p><p>Real resource queues, OS process termination, reversal of external effects, and real tool behavior after authorization changes remain outside the verified scope. Publication adds no new product experiment.</p>',57))])}const b=o(d,[["render",p]]);export{m as __pageData,b as default};
